/* Card set: SpongeBob (generated from the approved roster by the SpongeBob build, schema per tools/csv-to-set.js).
   (spongebob.js exceeds the comfortable push size, so the remaining cards live in
   spongebob-additions.js, which must stay directly after 'spongebob.js' in sets/manifest.js.) */
CardSets.register({"id":"spongebob","name":"SpongeBob","code":"SPON","description":"420 cards from Bikini Bottom — SpongeBob and friends, classic episodes, Krabby Patties and inventions, beloved locations, sea creatures, running gags, and songs.","theme":{"primary":"#ffe135","secondary":"#2674b8","artBackground":"#fffbe0","artFit":"cover"},"pack":{"name":"SpongeBob Pack","emblem":"🧽","skin":"spongebob"},"cards":[{"name":"SpongeBob SquarePants","rarity":"chase","id":"spongebob-squarepants","subtitle":"Characters","details":"Cheerful fry cook at the Krusty Krab who lives in a pineapple under the sea. His laughter, optimism, and jellyfishing spirit define Bikini Bottom.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/63/SpongeBob_SquarePants_stock_art.png/revision/latest/scale-to-width-down/500?cb=20220724205336"},{"name":"Patrick Star","rarity":"chase","id":"patrick-star","subtitle":"Characters","details":"SpongeBob's best friend, a pink starfish who lives under a rock. Dim but loyal, he loves jellyfishing, eating, and doing absolutely nothing at all.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5f/Patrick_stock_art_%28oil_painted%29.png/revision/latest/scale-to-width-down/500?cb=20220801050245"},{"name":"Squidward Tentacles","rarity":"chase","id":"squidward-tentacles","subtitle":"Characters","details":"SpongeBob's grumpy octopus neighbor and Krusty Krab cashier. He dreams of fame as a clarinetist and artist, far away from his cheerful neighbors.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/49/Squidward_unhappy_stock_art.png/revision/latest/scale-to-width-down/500?cb=20251102234328"},{"name":"Mr. Krabs","rarity":"chase","id":"mr-krabs","subtitle":"Characters","details":"Founder of the Krusty Krab and keeper of the Krabby Patty secret formula. This red crab loves money above almost everything else in the sea.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/7f/Eugene_Krabs.png/revision/latest/scale-to-width-down/500?cb=20251118195241"},{"name":"Sandy Cheeks","rarity":"chase","id":"sandy-cheeks","subtitle":"Characters","details":"A squirrel scientist from Texas who lives in an air-filled treedome. She studies sea life, practices karate, and builds wild inventions.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/19/Sandy_arm_out_%28oil_painted%29.png/revision/latest/scale-to-width-down/500?cb=20220801050159"},{"name":"Plankton","rarity":"chase","id":"plankton","subtitle":"Characters","details":"Tiny owner of the Chum Bucket who schemes endlessly to steal the Krabby Patty formula. His computer wife Karen helps hatch his evil plans.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/6b/EvilPlankton24.png/revision/latest/scale-to-width-down/500?cb=20251104033338"},{"name":"Gary the Snail","rarity":"chase","id":"gary-the-snail","subtitle":"Characters","details":"SpongeBob's pet snail, who meows like a cat and is far wiser than he looks. He loves books, poetry, and a full bowl of Snail-Po at mealtime.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/96/300px-SpongeBob_SquarePants_Gary_the_Snail_Transparent_PNG.png/revision/latest/scale-to-width-down/500?cb=20251103060900"},{"name":"DoodleBob","rarity":"chase","id":"doodlebob","subtitle":"Characters","details":"A living doodle drawn to life by a magic pencil. This chaotic paper SpongeBob speaks in scribbles and nearly erases his creator for good.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/07/DoodleBob_Stock_Art.png/revision/latest/scale-to-width-down/500?cb=20230220031315"},{"name":"Sweet Victory","rarity":"chase","id":"sweet-victory","subtitle":"Songs","details":"The triumphant power ballad performed by Squidward's band at the Bubble Bowl, turning a ragtag marching band into halftime legends before a roaring crowd.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/59/Band_Geeks_182.png/revision/latest/scale-to-width-down/500?cb=20191124035256"},{"name":"The Krabby Patty","rarity":"chase","id":"the-krabby-patty","subtitle":"Food, Inventions & Objects","details":"A sesame-seed bun sandwich built on a secret-formula patty with lettuce, cheese, pickles, tomato, onion, ketchup and mustard at the Krusty Krab.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/65/Krabby_Patty_stock_art.png/revision/latest/scale-to-width-down/500?cb=20200501165746"},{"name":"Mrs. Puff","rarity":"legendary","id":"mrs-puff","subtitle":"Characters","details":"Owner of Mrs. Puff's Boating School, where SpongeBob has failed his driving test countless times. She puffs up in panic whenever he takes the wheel.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/23/Mrs._Puff_stock_art.png/revision/latest/scale-to-width-down/500?cb=20251128153108"},{"name":"Pearl Krabs","rarity":"legendary","id":"pearl-krabs","subtitle":"Characters","details":"Mr. Krabs' teenage whale daughter, a cheerleader who loves shopping, boy bands, and parties. Her tears can flood a room when she gets upset.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ef/SpongeBob_SquarePants_-_Pearl_Krabs_promo_art.png/revision/latest/scale-to-width-down/500?cb=20181121020849"},{"name":"Karen Plankton","rarity":"legendary","id":"karen-plankton","subtitle":"Characters","details":"Plankton's waterproof computer wife, built from a calculator and a security system. She devises most of his plans and mocks his failures.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/18/Karen-blue-form-stock-art.png/revision/latest?cb=20200317150606"},{"name":"Larry the Lobster","rarity":"legendary","id":"larry-the-lobster","subtitle":"Characters","details":"Muscular lifeguard of Goo Lagoon and gym enthusiast. This friendly lobster loves tanning, working out, and living the healthy beach life.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/05/Larry_the_Lobster_stock_image_standing.png/revision/latest/scale-to-width-down/500?cb=20251031061723"},{"name":"Mermaid Man","rarity":"legendary","id":"mermaid-man","subtitle":"Characters","details":"Retired superhero of Bikini Bottom, once the brave defender of the sea. He lives at Shady Shoals and leaps into action at the cry of evil.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/ca/Mermaid_Man_stock_art.png/revision/latest/scale-to-width-down/500?cb=20220807020103"},{"name":"Barnacle Boy","rarity":"legendary","id":"barnacle-boy","subtitle":"Characters","details":"Mermaid Man's loyal sidekick, a retired hero tired of being treated like a child. He craves respect and an adult-sized Krabby Patty meal.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d5/Barnacle_Boy_stock_art.png/revision/latest/scale-to-width-down/500?cb=20220807020111"},{"name":"Flying Dutchman","rarity":"legendary","id":"flying-dutchman","subtitle":"Characters","details":"Ghostly pirate captain who sails a haunted ship and frightens Bikini Bottom. He collects souls, tells sea tales, and loses bets to SpongeBob.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/ba/Flying_Dutchman.png/revision/latest/scale-to-width-down/500?cb=20260320184443"},{"name":"King Neptune","rarity":"legendary","id":"king-neptune","subtitle":"Characters","details":"Powerful ruler of the sea who wields a magical trident. He once challenged Mr. Krabs and SpongeBob over the worth of a fry cook's patty.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a2/King_Neptune_model_pose.png/revision/latest/scale-to-width-down/500?cb=20240114052847"},{"name":"Squilliam Fancyson","rarity":"legendary","id":"squilliam-fancyson","subtitle":"Characters","details":"Squidward's rich and successful rival from band class. This fancy octopus owns a mansion, a private yacht, and delights in showing off.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/7a/Squilliam_model_pose_transparent.png/revision/latest/scale-to-width-down/500?cb=20251124191913"},{"name":"Bubble Bass","rarity":"legendary","id":"bubble-bass","subtitle":"Characters","details":"A picky bass and Krusty Krab critic famed for an impossibly complex order. He hid the pickles under his tongue to claim a free lunch.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/ba/Bubble_Bass_model.png/revision/latest/scale-to-width-down/500?cb=20220807054053"},{"name":"Man Ray","rarity":"legendary","id":"man-ray","subtitle":"Characters","details":"Mermaid Man's manta-ray archenemy, a villain stopped by his tickle belt. He once tried to learn goodness from SpongeBob and Patrick.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/3d/Man_ray_model.png/revision/latest/scale-to-width-down/500?cb=20220807062030"},{"name":"Dirty Bubble","rarity":"legendary","id":"dirty-bubble","subtitle":"Characters","details":"Mermaid Man's filthy bubble archenemy, a villain made of grime. He traps heroes inside himself and is finally undone by a sharp pencil.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f8/Dirty_Bubble_model.png/revision/latest/scale-to-width-down/500?cb=20230220151825"},{"name":"Band Geeks","rarity":"legendary","id":"band-geeks","subtitle":"Episodes & Iconic Moments","details":"Squidward assembles Bikini Bottom residents into a marching band to outshine Squilliam, and SpongeBob leads them to a triumphant stadium show.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/40/Band_Geeks_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626204844"},{"name":"Chocolate with Nuts","rarity":"legendary","id":"chocolate-with-nuts","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick become door-to-door chocolate salesmen, facing a frantic con man and an elderly customer who finally buys every single bar.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/47/Chocolate_with_Nuts_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308145643"},{"name":"Pizza Delivery","rarity":"legendary","id":"pizza-delivery","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Squidward get lost in the desert delivering the Krusty Krab's first pizza, and a pioneer rock becomes their unlikely ride home.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/29/Pizza_Delivery_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304105400"},{"name":"Help Wanted","rarity":"legendary","id":"help-wanted","subtitle":"Episodes & Iconic Moments","details":"SpongeBob applies for the Krusty Krab fry cook job, buys a fancy spatula, and saves the restaurant from a busload of hungry anchovies on day one.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/dd/Help_Wanted_title_card.png/revision/latest/scale-to-width-down/600?cb=20180715155842"},{"name":"Rock Bottom (episode)","rarity":"legendary","id":"rock-bottom-episode","subtitle":"Episodes & Iconic Moments","details":"Stranded in the dark, deep-sea town of Rock Bottom, SpongeBob struggles with strange customs and a bus schedule that keeps leaving without him.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2a/Rock_Bottom_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304114433"},{"name":"Graveyard Shift","rarity":"legendary","id":"graveyard-shift","subtitle":"Episodes & Iconic Moments","details":"Working the night shift, Squidward terrifies SpongeBob with the tale of the Hash-Slinging Slasher, until a mysterious figure arrives at the door.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/3f/Graveyard_Shift_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626205025"},{"name":"Golden Spatula","rarity":"legendary","id":"golden-spatula","subtitle":"Food, Inventions & Objects","details":"King Neptune's golden spatula, wielded by a fry cook worthy of the gods. SpongeBob pulls it from solid grease in a legendary test of skill.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/7f/Plankton%21_057.png/revision/latest/scale-to-width-down/500?cb=20211011053700"},{"name":"Magic Conch Shell","rarity":"legendary","id":"magic-conch-shell","subtitle":"Food, Inventions & Objects","details":"A purple shell toy that answers yes-or-no questions when its string is pulled. Stranded in the Kelp Forest, the gang obeys its every ruling.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e4/Magic_Conch_Shell.png/revision/latest/scale-to-width-down/500?cb=20250108221006"},{"name":"Patty Wagon","rarity":"legendary","id":"patty-wagon","subtitle":"Food, Inventions & Objects","details":"A drivable burger on wheels with pickle wheels and a sesame bun body. SpongeBob and Patrick ride it across the sea on their Shell City quest.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/43/SpongeBob_and_Patrick_Patty_Wagon.png/revision/latest/scale-to-width-down/500?cb=20230227051205"},{"name":"The Krusty Krab","rarity":"legendary","id":"the-krusty-krab","subtitle":"Bikini Bottom Locations","details":"Home of the Krabby Patty, this boat-shaped Bikini Bottom eatery is run by Mr. Krabs, with SpongeBob at the grill and Squidward at the register.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/77/KrustyKrabStock.png/revision/latest/scale-to-width-down/600?cb=20221031053149"},{"name":"SpongeBob's Pineapple House","rarity":"legendary","id":"spongebobs-pineapple-house","subtitle":"Bikini Bottom Locations","details":"A ripe pineapple dropped from a boat became SpongeBob's cozy home on Conch Street, complete with a library, a garage, and Gary's snail bed.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/7c/SpongeBobHouseStock.png/revision/latest/scale-to-width-down/600?cb=20221031053603"},{"name":"Bikini Bottom","rarity":"legendary","id":"bikini-bottom","subtitle":"Bikini Bottom Locations","details":"A lively undersea city on the Pacific Ocean floor, Bikini Bottom is home to SpongeBob and his friends, with kelp forests and flower clouds.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/26/Bubbletown_002.png/revision/latest/scale-to-width-down/600?cb=20181028171458"},{"name":"Alaskan Bull Worm","rarity":"legendary","id":"alaskan-bull-worm","subtitle":"Creatures","details":"A gigantic pink worm that terrorized Bikini Bottom, swallowing buildings whole before Sandy wrestled it over the edge of a steep cliff.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/ae/AlaskanBullWorm.png/revision/latest/scale-to-width-down/600?cb=20230608001859"},{"name":"Sea Bear","rarity":"legendary","id":"sea-bear","subtitle":"Creatures","details":"A fearsome hybrid creature that attacks anyone who draws its attention, repelled only by an anti-sea-bear circle drawn in the sand.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/86/Normal_sea_bear.png/revision/latest/scale-to-width-down/600?cb=20261011132254"},{"name":"Mocking SpongeBob","rarity":"legendary","id":"mocking-spongebob","subtitle":"Memes, Quotes & Running Gags","details":"SpongeBob hunches, crosses his eyes and clucks like a chicken at the sight of plaid, a pose fans turned into the sticky-caps reply for mocking any claim.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/fe/Mocking_SpongeBob.png/revision/latest?cb=20190208153151"},{"name":"CHOCOLATE!","rarity":"legendary","id":"chocolate","subtitle":"Memes, Quotes & Running Gags","details":"A mild-mannered customer snaps at the sight of a chocolate bar and chases SpongeBob and Patrick down the street screaming one word at the top of his lungs.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/78/Chocolate_with_Nuts_186.png/revision/latest/scale-to-width-down/500?cb=20250722191603"},{"name":"Goofy Goober Rock","rarity":"legendary","id":"goofy-goober-rock","subtitle":"Songs","details":"SpongeBob's blazing rock performance in the first film, shredding a guitar solo that breaks Plankton's mind-control helmets and frees Bikini Bottom.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/88/The_SpongeBob_SquarePants_Movie_777.png/revision/latest/scale-to-width-down/500?cb=20190223052513"},{"name":"Ripped Pants (song)","rarity":"legendary","id":"ripped-pants-song","subtitle":"Songs","details":"A beachside apology song about a fool who ripped his pants for laughs, performed with the Losers after SpongeBob's joke drives Sandy away.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/75/Ripped_Pants_174.png/revision/latest/scale-to-width-down/500?cb=20260719063425"},{"name":"Patchy the Pirate","rarity":"epic","id":"patchy-the-pirate","subtitle":"Characters","details":"SpongeBob's biggest fan, a live-action pirate who hosts special episodes from his home. He leads the SpongeBob fan club with Potty the Parrot.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2a/SpongeBob-Patchy-the-Pirate-promo-pose.jpg/revision/latest/scale-to-width-down/325?cb=20220321155202"},{"name":"Potty the Parrot","rarity":"epic","id":"potty-the-parrot","subtitle":"Characters","details":"Patchy the Pirate's sarcastic puppet parrot and co-host. This stringy bird mocks Patchy's hosting and steals scenes with dry one-liners.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/24/SpongeBob-Potty-the-Parrot.png/revision/latest/scale-to-width-down/500?cb=20200304030214"},{"name":"French Narrator","rarity":"epic","id":"french-narrator","subtitle":"Characters","details":"The unseen narrator whose calm voice opens episodes and marks time passing. His famous cards announce moments like a few moments later.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/34/You%27re_Going_to_Pay...Phone_142.png/revision/latest/scale-to-width-down/500?cb=20230414092240"},{"name":"Perch Perkins","rarity":"epic","id":"perch-perkins","subtitle":"Characters","details":"Bikini Bottom's purple perch news reporter, seen covering big events and disasters. He reports live from the scene, rain, shine, or chaos.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e3/Orange_perch.png/revision/latest/scale-to-width-down/500?cb=20220807053607"},{"name":"Princess Mindy","rarity":"epic","id":"princess-mindy","subtitle":"Characters","details":"King Neptune's kind mermaid daughter, who believes in SpongeBob and Patrick. She helps them face danger on the road to Shell City.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/47/Princess_Mindy.png/revision/latest/scale-to-width-down/440?cb=20231003193135"},{"name":"Burger Beard","rarity":"epic","id":"burger-beard","subtitle":"Characters","details":"The pirate villain who steals the Krabby Patty formula and turns his ship into a food truck. The superhero team Plankton assembled stops him.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/84/Burger_Beard_the_Pirate.png/revision/latest/scale-to-width-down/351?cb=20251026114615"},{"name":"King Poseidon","rarity":"epic","id":"king-poseidon","subtitle":"Characters","details":"Vain ruler of Atlantic City who keeps Gary as a pet for his snail slime. His showdown with SpongeBob becomes a musical act of friendship.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/24/Poseidon_SBM3.png/revision/latest/scale-to-width-down/500?cb=20220807055644"},{"name":"Lord Royal Highness","rarity":"epic","id":"lord-royal-highness","subtitle":"Characters","details":"Ruler of Atlantis, a short blue Atlantean who guards the world's oldest bubble. He tours SpongeBob's crew through his city's treasures.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/03/Lord_Royal_Highness.png/revision/latest/scale-to-width-down/369?cb=20230224025724"},{"name":"Dennis","rarity":"epic","id":"dennis","subtitle":"Characters","details":"The ruthless hitman hired to stop SpongeBob and Patrick on their way to Shell City. His spiked boots meet their match in the Cyclops.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/36/Dennis_Stock_Image.png/revision/latest/scale-to-width-down/500?cb=20221229005414"},{"name":"Squidly Tentacles","rarity":"epic","id":"squidly-tentacles","subtitle":"Characters","details":"Squidward's medieval ancestor, a royal jester and clarinet player in King Krabs' court. He was jailed, freed, and cursed across seven years of bad luck.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e7/Squidly_Stock_Art.png/revision/latest/scale-to-width-down/322?cb=20230220043840"},{"name":"SpongeBuck SquarePants","rarity":"epic","id":"spongebuck-squarepants","subtitle":"Characters","details":"SpongeBob's western ancestor, a singing fry cook who became sheriff of Dead Eye Gulch. He faced down Dead Eye Plankton in a showdown.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/50/SpongeBuck_stock_art.jpeg/revision/latest/scale-to-width-down/500?cb=20220112172337"},{"name":"Invincibubble","rarity":"epic","id":"invincibubble","subtitle":"Characters","details":"SpongeBob's superhero form, granted power by Bubbles the dolphin. He blows a mighty bubble helmet and leads the team against Burger Beard.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5f/Invincibubble_pointing.png/revision/latest/scale-to-width-down/500?cb=20221018012553"},{"name":"Bubble Buddy","rarity":"epic","id":"bubble-buddy","subtitle":"Characters","details":"SpongeBob's bubble friend, blown to life on Leif Erikson Day. The town turned on this silent buddy, who finally drove off in a bubble taxi.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/6b/Bubble_Buddy_character_in_Bubble_Buddy.png/revision/latest?cb=20150117225012"},{"name":"Flats the Flounder","rarity":"epic","id":"flats-the-flounder","subtitle":"Characters","details":"A tough flounder at Mrs. Puff's Boating School who vowed to kick SpongeBob's butt. His threats failed because SpongeBob felt no pain at all.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9d/Typing_Flats.png/revision/latest?cb=20200831020241"},{"name":"Tattletale Strangler","rarity":"epic","id":"tattletale-strangler","subtitle":"Characters","details":"A criminal who swore revenge on whoever reported his littering. SpongeBob hired him as a bodyguard, unaware of who he really was.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c7/The_Tattletale_Strangler.png/revision/latest/scale-to-width-down/427?cb=20230701063325"},{"name":"Shanghaied","rarity":"epic","id":"shanghaied","subtitle":"Episodes & Iconic Moments","details":"SpongeBob, Patrick and Squidward end up aboard the Flying Dutchman's ship, where a perfume department and a wishing well test their three wishes.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/7b/Shanghaied_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626071449"},{"name":"Dying for Pie","rarity":"epic","id":"dying-for-pie","subtitle":"Episodes & Iconic Moments","details":"Squidward gives SpongeBob a pie that is actually a bomb, then guiltily tries to make the fry cook's supposed final day the best day ever.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a5/Dying_for_Pie_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626070336"},{"name":"Idiot Box","rarity":"epic","id":"idiot-box","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick play inside a cardboard box using only imagination, producing sounds so real that Squidward cannot resist investigating.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/34/Idiot_Box_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308145310"},{"name":"The Camping Episode","rarity":"epic","id":"the-camping-episode","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick camp ten feet from home and torment Squidward with a sea bear, which attacks anyone who breaks their silly safety rules.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e6/The_Camping_Episode_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308150026"},{"name":"Krusty Krab Training Video","rarity":"epic","id":"krusty-krab-training-video","subtitle":"Episodes & Iconic Moments","details":"A vintage-style training film teaches new hires about POOP, the Krabby Patty secret, and what it takes to serve customers at the Krusty Krab.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/dc/Krusty_Krab_Training_Video_title_card.png/revision/latest/scale-to-width-down/600?cb=20240617052300"},{"name":"Ripped Pants","rarity":"epic","id":"ripped-pants","subtitle":"Episodes & Iconic Moments","details":"SpongeBob rips his pants for a laugh at Goo Lagoon, rides the joke far too long, and wins Sandy and the crowd back with a sincere beach song.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/14/Ripped_Pants_title_card.png/revision/latest/scale-to-width-down/600?cb=20240725020907"},{"name":"Frankendoodle","rarity":"epic","id":"frankendoodle","subtitle":"Episodes & Iconic Moments","details":"A magic pencil brings a doodle of SpongeBob to life as the mischievous DoodleBob, and only an ordinary sheet of paper can trap him for good.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f1/Frankendoodle_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626204636"},{"name":"Bubble Buddy (episode)","rarity":"epic","id":"bubble-buddy-episode","subtitle":"Episodes & Iconic Moments","details":"Feeling left out, SpongeBob invents a friend made of bubbles, and Bubble Buddy's rude behavior angers everyone at Goo Lagoon on a busy day.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8a/Bubble_Buddy_title_card.png/revision/latest/scale-to-width-down/600?cb=20231230003740"},{"name":"Squidville","rarity":"epic","id":"squidville","subtitle":"Episodes & Iconic Moments","details":"Squidward moves to Tentacle Acres, a gated town of Squidwards, then grows bored with the perfect routine and longs for his old Bikini Bottom life.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/28/Squidville_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626070746"},{"name":"Just One Bite","rarity":"epic","id":"just-one-bite","subtitle":"Episodes & Iconic Moments","details":"Squidward claims to hate Krabby Patties without ever tasting one, then sneaks back at night and devours the entire vault in a feeding frenzy.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c8/Just_One_Bite_title_card.png/revision/latest/scale-to-width-down/600?cb=20240701090950"},{"name":"Pretty Patties","rarity":"epic","id":"pretty-patties","subtitle":"Food, Inventions & Objects","details":"Krabby Patties dyed in bright rainbow colors and sold from a stand. Bikini Bottom lines up for them, until the colors stain every customer's tongue.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/36/Pretty_Patties.png/revision/latest/scale-to-width-down/500?cb=20260322174005"},{"name":"Jelly Patty","rarity":"epic","id":"jelly-patty","subtitle":"Food, Inventions & Objects","details":"A Krabby Patty topped with purple jellyfish jelly, invented after SpongeBob befriends a wild jellyfish and brings home a jar of its sweet jelly.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/02/Jelly_Patty.png/revision/latest/scale-to-width-down/500?cb=20251223100525"},{"name":"Triple Gooberberry Sunrise","rarity":"epic","id":"triple-gooberberry-sunrise","subtitle":"Food, Inventions & Objects","details":"A towering banana-and-fudge sundae served at Goofy Goober's Ice Cream Party Boat, big enough to leave SpongeBob and Patrick happily ice-cream drunk.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/29/Triple_Gooberberry_Sunrise.png/revision/latest/scale-to-width-down/500?cb=20260501193719"},{"name":"Krabby Patty Secret Formula","rarity":"epic","id":"krabby-patty-secret-formula","subtitle":"Food, Inventions & Objects","details":"The handwritten recipe for Krabby Patties, kept in a bottle and guarded by Mr. Krabs. Plankton devotes his life to stealing this single secret.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ea/Krabby_Patty_secret_formula.png/revision/latest/scale-to-width-down/500?cb=20180113044510"},{"name":"Spat","rarity":"epic","id":"spat","subtitle":"Food, Inventions & Objects","details":"SpongeBob's beloved spatula, his partner at the Krusty Krab grill since his first day. He talks to Spat, polishes it, and grieves when it breaks.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/26/Spat_stock_art_2014.png/revision/latest/scale-to-width-down/500?cb=20181228013627"},{"name":"Clarry, Squidward's Clarinet","rarity":"epic","id":"clarry-squidwards-clarinet","subtitle":"Food, Inventions & Objects","details":"Squidward's treasured clarinet, played in recitals, talent shows and quiet evenings at home. Its squawking solos delight Squidward and torment neighbors.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d0/ClarryStock.png/revision/latest/scale-to-width-down/500?cb=20221017013206"},{"name":"The Chum Bucket","rarity":"epic","id":"the-chum-bucket","subtitle":"Bikini Bottom Locations","details":"Plankton's failing restaurant and laboratory sits across from the Krusty Krab, serving chum that almost nobody in Bikini Bottom wants to eat.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d4/Single-Celled_Defense_020.png/revision/latest/scale-to-width-down/600?cb=20231103051012"},{"name":"Sandy's Treedome","rarity":"epic","id":"sandys-treedome","subtitle":"Bikini Bottom Locations","details":"Sandy's air-filled glass dome holds a grassy yard and a great oak tree, letting the Texas squirrel live underwater while breathing fresh air.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/02/Sandy%27s_Treedome_in_the_3rd_Movie.png/revision/latest/scale-to-width-down/600?cb=20230119072630"},{"name":"Jellyfish Fields","rarity":"epic","id":"jellyfish-fields","subtitle":"Bikini Bottom Locations","details":"Rolling meadows of coral and cliffs where wild jellyfish drift in huge numbers, making this the favorite jellyfishing ground of Bikini Bottom.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a6/Squirrel_Jelly_058.png/revision/latest/scale-to-width-down/600?cb=20181118154030"},{"name":"Squidward's Easter Island Head House","rarity":"epic","id":"squidwards-easter-island-head-house","subtitle":"Bikini Bottom Locations","details":"Squidward's home, carved like a giant Easter Island head, sits between SpongeBob and Patrick, much to its owner's daily frustration and regret.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/60/SquidwardHouseStock.png/revision/latest/scale-to-width-down/600?cb=20221031053839"},{"name":"Patrick's Rock","rarity":"epic","id":"patricks-rock","subtitle":"Bikini Bottom Locations","details":"Patrick lives under a simple brown rock on Conch Street, where the furniture is made of sand and everything is only a nap away from his bed.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5d/PatrickHouseStock.png/revision/latest/scale-to-width-down/600?cb=20221031054015"},{"name":"Mystery the Seahorse","rarity":"epic","id":"mystery-the-seahorse","subtitle":"Creatures","details":"A wild seahorse SpongeBob befriended and briefly kept, whose enormous appetite for Krabby Patties caused chaos at the Krusty Krab grill.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/35/My_Pretty_Seahorse_058.png/revision/latest/scale-to-width-down/600?cb=20200811201610"},{"name":"Giant Clam","rarity":"epic","id":"giant-clam","subtitle":"Creatures","details":"Enormous clams lurk in Bikini Bottom's waters, and one famous giant stole Mr. Krabs' millionth dollar during a fishing trip gone wrong.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f2/Clam_Model_Pose.png/revision/latest/scale-to-width-down/600?cb=20251001221549"},{"name":"Sea Rhinoceros","rarity":"epic","id":"sea-rhinoceros","subtitle":"Creatures","details":"Even scarier than a sea bear, this huge beast is drawn by the sound of a sea bear attack, and only special undergarments can deter it.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/97/The_Camping_Episode_200.png/revision/latest/scale-to-width-down/600?cb=20200926025026"},{"name":"Queen Jellyfish","rarity":"epic","id":"queen-jellyfish","subtitle":"Creatures","details":"A huge, regal jellyfish encountered on a jellyfishing trip, far larger and more dangerous than the common pink jellies of the fields.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d5/Queen_jellyfish.png/revision/latest/scale-to-width-down/600?cb=20260617125936"},{"name":"I'm Ready!","rarity":"epic","id":"im-ready","subtitle":"Memes, Quotes & Running Gags","details":"SpongeBob bursts from his pineapple chanting his catchphrase on the way to the Krusty Krab, the eager declaration that opens his workday and defines him.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f5/Help_Wanted_016.png/revision/latest/scale-to-width-down/500?cb=20191210003600"},{"name":"My Leg!","rarity":"epic","id":"my-leg","subtitle":"Memes, Quotes & Running Gags","details":"Fred the fish cries out in pain whenever chaos strikes Bikini Bottom, a stock scream heard across seasons that turned a background fish into a legend.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2c/My_Leg%21_024.png/revision/latest/scale-to-width-down/500?cb=20180508205807"},{"name":"Is Mayonnaise an Instrument?","rarity":"epic","id":"is-mayonnaise-an-instrument","subtitle":"Memes, Quotes & Running Gags","details":"Patrick raises his hand in band practice and earnestly asks Squidward if mayonnaise counts as an instrument, then asks the same about horseradish too.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/1f/Is-mayonnaise-an-instrument.jpg/revision/latest?cb=20231124154210"},{"name":"The Imagination Box","rarity":"epic","id":"the-imagination-box","subtitle":"Memes, Quotes & Running Gags","details":"SpongeBob and Patrick sit in a plain cardboard box and conjure race cars and rocket ships from pure imagination, while Squidward fumes outside it all.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/87/Idiot_Box_064.png/revision/latest/scale-to-width-down/500?cb=20200805145726"},{"name":"Campfire Song Song","rarity":"epic","id":"campfire-song-song","subtitle":"Songs","details":"A fast-spelled singalong around an underwater campfire, led by SpongeBob with Patrick on drums, while Squidward refuses to join the spelling fun.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/94/Campfire_song_song.png/revision/latest/scale-to-width-down/500?cb=20221114043145"},{"name":"Gary Come Home","rarity":"epic","id":"gary-come-home","subtitle":"Songs","details":"SpongeBob's tearful ballad begging his runaway snail Gary to come home, sung over a city-wide search after Gary leaves in search of food and care.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/4b/Have_You_Seen_This_Snail_338.png/revision/latest/scale-to-width-down/500?cb=20200819172718"},{"name":"Painty the Pirate","rarity":"rare","id":"painty-the-pirate","subtitle":"Characters","details":"The singing pirate painting who opens every episode with a hearty are you ready, kids. His portrait hangs at the start of the theme song.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c5/SpongeBob_Intro_2016_%281%29.png/revision/latest/scale-to-width-down/500?cb=20160713155754"},{"name":"Realistic Fish Head","rarity":"rare","id":"realistic-fish-head","subtitle":"Characters","details":"The live-action fish head who announces Krusty Krab commercials and news. His gravelly voice sells everything from patties to training tapes.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c2/Realistic_Fish_Head.png/revision/latest/scale-to-width-down/500?cb=20241001062749"},{"name":"Goofy Goober","rarity":"rare","id":"goofy-goober","subtitle":"Characters","details":"Peanut mascot of Goofy Goober's Ice Cream Party Boat, a beloved kids' restaurant. SpongeBob and Patrick adore his song and sundaes.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/25/Goofy_Goober_stock_image.png/revision/latest/scale-to-width-down/500?cb=20191007191453"},{"name":"Handsome Squidward","rarity":"rare","id":"handsome-squidward","subtitle":"Characters","details":"Squidward's stunningly chiseled form after a door slammed into his face. The town adored his beauty until a second slam changed him again.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/3c/Handsome_Squidward.png/revision/latest?cb=20161130235132"},{"name":"Squog","rarity":"rare","id":"squog","subtitle":"Characters","details":"Squidward's prehistoric ancestor, a cave octopus who lived beside SpongeGar and Patar. He communicated in grunts and guarded his reef fiercely.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2a/Squog_model.png/revision/latest/scale-to-width-down/500?cb=20251125161035"},{"name":"SpongeGar","rarity":"rare","id":"spongegar","subtitle":"Characters","details":"SpongeBob's prehistoric ancestor, a primitive sponge who discovered fire and cooked the first patties. He rode a giant Gary and spoke in gibberish.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/eb/SpongeGar_Stock_Art.webp/revision/latest/scale-to-width-down/500?cb=20230204022658"},{"name":"Patar","rarity":"rare","id":"patar","subtitle":"Characters","details":"Patrick's prehistoric ancestor, a cave starfish as dim as his descendant. He ate a poisonous plant, survived, and befriended SpongeGar and Squog.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/76/Patar_model.png/revision/latest/scale-to-width-down/500?cb=20221225095140"},{"name":"Cyclops","rarity":"rare","id":"cyclops","subtitle":"Characters","details":"The giant diver of Shell City, feared by sea creatures as a monster. He captures SpongeBob and Patrick to dry them under a heat lamp.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/02/The_Cyclops.png/revision/latest/scale-to-width-down/378?cb=20230329213541"},{"name":"Bubbles the Dolphin","rarity":"rare","id":"bubbles-the-dolphin","subtitle":"Characters","details":"A wise dolphin guardian who watches over the galaxy from Bikini Bottom's waters. He grants SpongeBob's crew superpowers to save the formula.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2f/The_SpongeBob_Movie_Sponge_Out_of_Water_479.png/revision/latest/scale-to-width-down/500?cb=20190204022153"},{"name":"Sage","rarity":"rare","id":"sage","subtitle":"Characters","details":"A wise tumbleweed sage met on the road to Atlantic City. Rolling with the desert wind, he guides SpongeBob and Patrick with calm riddles.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/11/The_SpongeBob_Movie_Sponge_on_the_Run_408.png/revision/latest/scale-to-width-down/500?cb=20210105113833"},{"name":"El Diablo","rarity":"rare","id":"el-diablo","subtitle":"Characters","details":"A flamboyant undead gambler who runs the casino town of the lost souls. He chases SpongeBob and Patrick after they flee with his coin.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/92/El_Diablo_SOTR.png/revision/latest/scale-to-width-down/500?cb=20201105181359"},{"name":"Otto","rarity":"rare","id":"otto","subtitle":"Characters","details":"King Poseidon's cheerful robot assistant in Atlantic City, programmed to obey commands. He drives, announces guests, and follows orders literally.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/13/LightbulbBot.png/revision/latest/scale-to-width-down/500?cb=20220807055806"},{"name":"Nosferatu","rarity":"rare","id":"nosferatu","subtitle":"Characters","details":"The flickering-light vampire blamed for the Krusty Krab's night shift scares. This silent count later works the night shift himself at the Krab.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/6b/Noseferatu.jpg/revision/latest/scale-to-width-down/219?cb=20220806062034"},{"name":"Hash-Slinging Slasher","rarity":"rare","id":"hash-slinging-slasher","subtitle":"Characters","details":"The ghost of a clumsy fry cook from Squidward's scary night story. His arrival is heralded by flickering lights, a call, and a bus at night.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/bd/Hashslingingslasher.png/revision/latest/scale-to-width-down/500?cb=20220702150337"},{"name":"Kevin the Sea Cucumber","rarity":"rare","id":"kevin-the-sea-cucumber","subtitle":"Characters","details":"Leader of the Jellyspotters club, a smug sea cucumber in a crowned jellyfish hat. He mocked SpongeBob until jellyfish stung him senseless.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9f/Kevin_C._Cucumber_model.png/revision/latest/scale-to-width-down/500?cb=20230212044703"},{"name":"Jim","rarity":"rare","id":"jim","subtitle":"Characters","details":"The Krusty Krab's legendary original fry cook, whose patties won fame for the restaurant. Mr. Krabs refused him a raise, so he left in a limo.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9a/Jim.jpg/revision/latest/scale-to-width-down/287?cb=20260812125828"},{"name":"Smitty Werbenjagermanjensen","rarity":"rare","id":"smitty-werbenjagermanjensen","subtitle":"Characters","details":"He was number one, as his soda-drink hat proclaimed. SpongeBob honored this legendary fish's memory after finding his grave at the cemetery.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/ce/One_Krabs_Trash_160b.png/revision/latest/scale-to-width-down/500?cb=20210609051234"},{"name":"Jack Kahuna Laguna","rarity":"rare","id":"jack-kahuna-laguna","subtitle":"Characters","details":"A legendary surfing instructor who teaches kahuna at Kahuna Laguna. This laid-back guru guided SpongeBob, Patrick, and Squidward to the Big One.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/58/JKL_Stock_Art.png/revision/latest/scale-to-width-down/357?cb=20230220030650"},{"name":"Master Udon","rarity":"rare","id":"master-udon","subtitle":"Characters","details":"A karate master on Karate Island who lured Sandy with a title offer. His island was really a condo sales trap guarded by tough fighters.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a1/Master_Udon.png/revision/latest/scale-to-width-down/500?cb=20260702165936"},{"name":"Mini Squidward","rarity":"rare","id":"mini-squidward","subtitle":"Characters","details":"SpongeBob's ventriloquist dummy carved to look exactly like Squidward. The town loved the dummy, driving the real Squidward into a frenzy.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a5/Squid_Wood_%28Mini_Squid%29.png/revision/latest/scale-to-width-down/212?cb=20230407141706"},{"name":"The Dark Knight","rarity":"rare","id":"the-dark-knight","subtitle":"Characters","details":"Sandy's medieval ancestor, a knight in King Krabs' kingdom who battled the jellyfish dragon. She wielded a sword and karate in shining armor.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5e/Dark_Knight_Model.jpeg/revision/latest/scale-to-width-down/299?cb=20241227182832"},{"name":"Queen Amphitrite","rarity":"rare","id":"queen-amphitrite","subtitle":"Characters","details":"Queen of the sea and wife of King Neptune, mother of Triton and Mindy. This kind goddess balances Neptune's temper in the royal court.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/45/Queen_Amphitrite_model_pose_season_6.gif/revision/latest/scale-to-width-down/370?cb=20250802223752"},{"name":"Wet Painters","rarity":"rare","id":"wet-painters","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick paint Mr. Krabs' house and panic over a tiny drop on his first dollar, learning the paint washes off with a little saliva.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d2/Wet_Painters_title_card.png/revision/latest/scale-to-width-down/600?cb=20240701233152"},{"name":"Sailor Mouth","rarity":"rare","id":"sailor-mouth","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick learn a colorful word from a dumpster and use it everywhere, until Mr. Krabs teaches them why sailors keep it to themselves.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c7/Sailor_Mouth_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626205555"},{"name":"Christmas Who?","rarity":"rare","id":"christmas-who","subtitle":"Episodes & Iconic Moments","details":"SpongeBob brings Christmas to Bikini Bottom for the first time, and a grumpy Squidward learns generosity after playing Santa for the whole town.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/76/Christmas_Who%3F_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626070820"},{"name":"The Fry Cook Games","rarity":"rare","id":"the-fry-cook-games","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick compete for rival restaurants at the Fry Cook Games, and their fierce rivalry melts into friendship inside the arena.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e5/The_Fry_Cook_Games_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626205831"},{"name":"Club SpongeBob","rarity":"rare","id":"club-spongebob","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick worship a magic conch shell in their club, while a stranded Squidward refuses its advice and waits in vain for rescue.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/dd/Club_SpongeBob_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308145148"},{"name":"Arrgh!","rarity":"rare","id":"arrgh","subtitle":"Episodes & Iconic Moments","details":"Mr. Krabs turns a board game treasure hunt into a real dig for the Flying Dutchman's gold, with SpongeBob and Patrick dressed as eager pirates.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/26/Arrgh%21_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20231228184554"},{"name":"Texas","rarity":"rare","id":"texas","subtitle":"Episodes & Iconic Moments","details":"A homesick Sandy sings about Texas and plans to leave Bikini Bottom, so SpongeBob and Patrick throw her a surprise party to make her stay.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/69/Texas_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304114617"},{"name":"Jellyfish Jam","rarity":"rare","id":"jellyfish-jam","subtitle":"Episodes & Iconic Moments","details":"SpongeBob brings a wild jellyfish home and it throws an all-night dance party with hundreds of friends, wrecking the house until Gary intervenes.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/cf/Jellyfish_Jam_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20170113010845"},{"name":"Survival of the Idiots","rarity":"rare","id":"survival-of-the-idiots","subtitle":"Episodes & Iconic Moments","details":"Trapped inside Sandy's treedome during hibernation, SpongeBob and Patrick face a ferocious sleeping Sandy while dressed as Dirty Dan and Pinhead Larry.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/40/Survival_of_the_Idiots_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626071022"},{"name":"The Algae's Always Greener","rarity":"rare","id":"the-algaes-always-greener","subtitle":"Episodes & Iconic Moments","details":"Plankton swaps lives with Mr. Krabs using a device, discovers running the Krusty Krab is miserable, and begs to return to the Chum Bucket.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/cd/The_Algae%27s_Always_Greener_title_card.png/revision/latest/scale-to-width-down/600?cb=20240701091727"},{"name":"Fear of a Krabby Patty","rarity":"rare","id":"fear-of-a-krabby-patty","subtitle":"Episodes & Iconic Moments","details":"Plankton opens the Chum Bucket around the clock to exhaust SpongeBob, whose fear of patties is treated by a very suspicious Dr. Peter Lankton.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/3e/Fear_of_a_Krabby_Patty_title_card.png/revision/latest/scale-to-width-down/600?cb=20231103095509"},{"name":"Have You Seen This Snail?","rarity":"rare","id":"have-you-seen-this-snail","subtitle":"Episodes & Iconic Moments","details":"Gary runs away after SpongeBob neglects him for a paddle ball challenge, and a lonely search follows while a sweet granny hides a dark secret.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a8/Have_You_Seen_This_Snail%3F_title_card.png/revision/latest/scale-to-width-down/600?cb=20231103100946"},{"name":"Dunces and Dragons","rarity":"rare","id":"dunces-and-dragons","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick are sent to a medieval Bikini Bottom, where they join King Krabs' court and face Planktonamor and a fearsome jellyfish dragon.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9c/Dunces_and_Dragons_title_card.png/revision/latest/scale-to-width-down/600?cb=20231103100201"},{"name":"Something Smells","rarity":"rare","id":"something-smells","subtitle":"Episodes & Iconic Moments","details":"A sundae of onions, ketchup and a peanut plant gives SpongeBob terrible breath, and Patrick convinces him everyone fears him because he is ugly.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ef/Something_Smells_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626070047"},{"name":"Plankton's Army","rarity":"rare","id":"planktons-army","subtitle":"Episodes & Iconic Moments","details":"Plankton summons thousands of his relatives to steal the Krabby Patty formula, and the hillbilly clan discovers the secret ingredient is plankton.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d5/Plankton%27s_Army_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308150054"},{"name":"The Sponge Who Could Fly","rarity":"rare","id":"the-sponge-who-could-fly","subtitle":"Episodes & Iconic Moments","details":"SpongeBob dreams of flying with the jellyfish, endures ridicule from the town, and finally soars using an inflatable pair of pants and a hair dryer.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8e/The_Sponge_Who_Could_Fly_title_card.png/revision/latest/scale-to-width-down/600?cb=20230308150629"},{"name":"Krusty Krab Pizza","rarity":"rare","id":"krusty-krab-pizza","subtitle":"Food, Inventions & Objects","details":"A pizza assembled from Krabby Patties and delivered by boat across the desert of sand. SpongeBob insists it is the pizza meant for you and me.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5f/Krusty_Krab_Pizza.png/revision/latest/scale-to-width-down/500?cb=20230812043541"},{"name":"Kelp Shake","rarity":"rare","id":"kelp-shake","subtitle":"Food, Inventions & Objects","details":"A green kelp drink sold by the cup at a trendy stand, so popular that Mr. Krabs and Plankton team up to learn the secret behind its success.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/05/Best_Frenemies_012.png/revision/latest/scale-to-width-down/500?cb=20191117235659"},{"name":"Chum","rarity":"rare","id":"chum","subtitle":"Food, Inventions & Objects","details":"A bucket of minced fish guts served at Plankton's Chum Bucket across from the Krusty Krab. Almost nobody in Bikini Bottom can stomach a serving.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/55/Chum_stock.png/revision/latest/scale-to-width-down/500?cb=20250819110854"},{"name":"Invisible Boatmobile","rarity":"rare","id":"invisible-boatmobile","subtitle":"Food, Inventions & Objects","details":"Mermaid Man and Barnacle Boy's vehicle, which turns invisible along with its heroes. Finding the invisible ignition is half the challenge of driving it.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/51/Mermaid_Man_and_Barnacle_Boy_IV_043.png/revision/latest/scale-to-width-down/500?cb=20200809211214"},{"name":"Ol' Reliable","rarity":"rare","id":"ol-reliable","subtitle":"Food, Inventions & Objects","details":"SpongeBob's faithful jellyfishing net, carried since his earliest trips to Jellyfish Fields. He trusts Ol' Reliable over any newer, fancier net.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/84/Nature_Pants_072.png/revision/latest/scale-to-width-down/500?cb=20211126180444"},{"name":"Sandy's Rocketship","rarity":"rare","id":"sandys-rocketship","subtitle":"Food, Inventions & Objects","details":"A rocket ship built by Sandy for a trip to the moon. SpongeBob and Patrick sneak aboard, mistake Bikini Bottom for lunar ground, and hunt aliens.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8d/SandyRocketModel.png/revision/latest/scale-to-width-down/500?cb=20221230052333"},{"name":"Hydro-Dynamic Spatula","rarity":"rare","id":"hydro-dynamic-spatula","subtitle":"Food, Inventions & Objects","details":"A high-tech spatula with port-and-starboard attachments and turbo drive, sold at the Barg'N-Mart. SpongeBob buys it for his first Krusty Krab shift.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/70/Hydrodynamic_spat.jpg/revision/latest/scale-to-width-down/500?cb=20150117144644"},{"name":"Chum Burger","rarity":"rare","id":"chum-burger","subtitle":"Food, Inventions & Objects","details":"Plankton's burger made from chum, offered as the Chum Bucket's answer to the Krabby Patty. Its grey, lumpy filling explains its tiny customer base.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2b/The_chum_burger_friend_or_foe_OHH_YEAHHH%21%21%21%21%21%21%21.png/revision/latest/scale-to-width-down/500?cb=20200831215233"},{"name":"Patty Vault","rarity":"rare","id":"patty-vault","subtitle":"Food, Inventions & Objects","details":"A steel vault inside the Krusty Krab where Mr. Krabs stores a mountain of ready Krabby Patties, sealed behind a door marked Patty Vault in bold red.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/66/PattyVaultStock.png/revision/latest/scale-to-width-down/500?cb=20221229225754"},{"name":"Boatmobile","rarity":"rare","id":"boatmobile","subtitle":"Food, Inventions & Objects","details":"The boat-shaped car driven all over Bikini Bottom, steered like a vessel and parked like a car. SpongeBob keeps failing the test needed to drive one.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/47/Boatmobile_stock_art.png/revision/latest/scale-to-width-down/500?cb=20200501173032"},{"name":"Mrs. Puff's Boating School","rarity":"rare","id":"mrs-puffs-boating-school","subtitle":"Bikini Bottom Locations","details":"Mrs. Puff teaches the rules of boat driving at this schoolhouse, where one eager sponge student has failed the driving exam countless times.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/12/Lighthouse_Louie_001.png/revision/latest/scale-to-width-down/600?cb=20200527190216"},{"name":"Goo Lagoon","rarity":"rare","id":"goo-lagoon","subtitle":"Bikini Bottom Locations","details":"A hugely popular beach where Bikini Bottom's sea creatures surf, sunbathe, lift weights at Mussel Beach, and snack at the juice bar together.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d8/Patnocchio_117.png/revision/latest/scale-to-width-down/600?cb=20180807220241"},{"name":"Glove World","rarity":"rare","id":"glove-world","subtitle":"Bikini Bottom Locations","details":"A glove-themed amusement park beloved by SpongeBob and Patrick, packed with rides, games, mascots, and the terrifying Fiery Fist O' Pain ride.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/99/Roller_Cowards_171.png/revision/latest/scale-to-width-down/600?cb=20230102171413"},{"name":"Rock Bottom","rarity":"rare","id":"rock-bottom","subtitle":"Bikini Bottom Locations","details":"A dark, trench-deep city beyond a sheer cliff, where strange glowing creatures speak with raspberries and the buses rarely stop for outsiders.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/5b/Rock_Bottom_038.png/revision/latest/scale-to-width-down/600?cb=20260331113210"},{"name":"New Kelp City","rarity":"rare","id":"new-kelp-city","subtitle":"Bikini Bottom Locations","details":"A grim, distant metropolis once ruled by the Bubble Poppin' Boys, where SpongeBob lost his memory and briefly became the city's elected mayor.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e0/What_Ever_Happened_to_SpongeBob_178.png/revision/latest/scale-to-width-down/600?cb=20191117033044"},{"name":"The Salty Spitoon","rarity":"rare","id":"the-salty-spitoon","subtitle":"Bikini Bottom Locations","details":"The toughest joint in Bikini Bottom, a biker hangout where patrons settle arguments with fists and nobody is admitted without a real tough tale.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/53/The_Salty_Spitoon.png/revision/latest/scale-to-width-down/600?cb=20221116190853"},{"name":"Weenie Hut Jr.'s","rarity":"rare","id":"weenie-hut-jrs","subtitle":"Bikini Bottom Locations","details":"A friendly little restaurant built for gentle souls, complete with a robot waiter, soft-serve sundaes, and advice nobody asked for but gets.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/04/Wiener_Takes_All_044.png/revision/latest/scale-to-width-down/600?cb=20241119230512"},{"name":"Krusty Krab 2","rarity":"rare","id":"krusty-krab-2","subtitle":"Bikini Bottom Locations","details":"Mr. Krabs built this second Krusty Krab beside the original, naming SpongeBob its manager before a movie-sized adventure changed the plan.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/eb/The_Krusty_Krab_2.png/revision/latest/scale-to-width-down/600?cb=20240731053144"},{"name":"Shell City","rarity":"rare","id":"shell-city","subtitle":"Bikini Bottom Locations","details":"A dreaded dry-land gift shop in a surface town, feared by sea creatures as a place of doom, where captured toys and curios line the shelves.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/21/The_SpongeBob_SquarePants_Movie_631.png/revision/latest/scale-to-width-down/600?cb=20190223044441"},{"name":"Nematodes","rarity":"rare","id":"nematodes","subtitle":"Creatures","details":"A swarm of tiny, ravenous worms that drinks houses and devours everything in its path, leaving only dust behind when the swarm moves on.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a7/Home_Sweet_Pineapple_010.png/revision/latest/scale-to-width-down/600?cb=20191214223337"},{"name":"Anchovies","rarity":"rare","id":"anchovies","subtitle":"Creatures","details":"These tiny fish travel in enormous, chattering schools, flooding the Krusty Krab at lunch hour with a single deafening cry of meep.","image":"https://vignette.wikia.nocookie.net/spongebob/images/3/31/Help_Wanted_105.png/revision/latest/scale-to-width-down/600?cb=20191210010046"},{"name":"Blue Jellyfish","rarity":"rare","id":"blue-jellyfish","subtitle":"Creatures","details":"A rare and elusive jellyfish of Jellyfish Fields, prized by jellyfishers for its beauty and famously difficult to catch in a net or jar.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/98/Blue_Jellyfish.png/revision/latest/scale-to-width-down/600?cb=20200319185138"},{"name":"Dragon Jellyfish","rarity":"rare","id":"dragon-jellyfish","subtitle":"Creatures","details":"A jellyfish shaped like a mighty dragon, glimpsed among the exotic varieties that drift through the wildest parts of Jellyfish Fields.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/94/Dragon_jellyfish_model.jpeg/revision/latest/scale-to-width-down/600?cb=20241227183502"},{"name":"Sea Urchins","rarity":"rare","id":"sea-urchins","subtitle":"Creatures","details":"Spiny little creatures that infest homes and pineapple houses, nibbling at everything and proving surprisingly hard to sweep away.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/bd/Eek%2C_an_Urchin%21_018.png/revision/latest/scale-to-width-down/600?cb=20181211210613"},{"name":"Sea Whelks","rarity":"rare","id":"sea-whelks","subtitle":"Creatures","details":"Snail-hunting mollusks whose sudden arrival in Bikini Bottom spelled trouble for Gary and every other snail living within city limits.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/90/ROAR%21%21%21%21.png/revision/latest/scale-to-width-down/600?cb=20220725201019"},{"name":"Abominable Snow Mollusk","rarity":"rare","id":"abominable-snow-mollusk","subtitle":"Creatures","details":"A hulking, hairy mollusk of the frozen north, feared in sailor tales and encountered during a chilly adventure far from Bikini Bottom.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/c3/Frozen_Face-Off_130.png/revision/latest/scale-to-width-down/600?cb=20211026115542"},{"name":"Firmly Grasp It","rarity":"rare","id":"firmly-grasp-it","subtitle":"Memes, Quotes & Running Gags","details":"Patrick delivers dead-serious jellyfishing instruction, ordering SpongeBob to firmly grasp the net in his hand, a solemn lesson fans repeat for any tool.","image":"https://vignette.wikia.nocookie.net/spongebob/images/5/52/Spongebob-_FIRMLY_GRASP_IT/revision/latest?cb=20230613040730"},{"name":"Wumbo","rarity":"rare","id":"wumbo","subtitle":"Memes, Quotes & Running Gags","details":"Patrick explains that the opposite of mini is wumbo, a setting on Mermaid Man's belt that he insists everyone learned back in the third grade already.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/dd/Wumbo-0.png/revision/latest?cb=20190405180421"},{"name":"Sea Bear Circle","rarity":"rare","id":"sea-bear-circle","subtitle":"Memes, Quotes & Running Gags","details":"SpongeBob and Patrick draw a circle in the dirt to repel a sea bear, warning that an oval invites attack, while Squidward mocks the ritual and pays dearly.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/23/The_Camping_Episode_165.png/revision/latest/scale-to-width-down/500?cb=20200926024542"},{"name":"Future!","rarity":"rare","id":"future","subtitle":"Memes, Quotes & Running Gags","details":"A stranded Squidward wanders a chrome world of the far future chanting the word in wonder, his echoing cry becoming shorthand for anything gleaming and ahead.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ee/SB-129_074.png/revision/latest/scale-to-width-down/500?cb=20260720114118"},{"name":"He's Just Standing There... Menacingly!","rarity":"rare","id":"menacingly","subtitle":"Memes, Quotes & Running Gags","details":"Patrick peers through binoculars and gravely reports that the villain is just standing there menacingly, a warning fans apply to any figure standing still.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ef/Mermaid_Man_and_Barnacle_Boy_II_140.png/revision/latest/scale-to-width-down/500?cb=20221208051204"},{"name":"Krusty Krab Pizza Delivery Chant","rarity":"rare","id":"krusty-krab-pizza-chant","subtitle":"Memes, Quotes & Running Gags","details":"SpongeBob sings that the Krusty Krab pizza is the pizza for you and me, turning a long delivery trek on foot into a joyful rock anthem to keep moving.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/11/Pizza_Delivery_148.png/revision/latest/scale-to-width-down/500?cb=20211231101227"},{"name":"The Best Day Ever","rarity":"rare","id":"the-best-day-ever","subtitle":"Songs","details":"A joyful song about a perfect day of karate, jellyfishing and work at the Krusty Krab, sung as SpongeBob refuses to let anything ruin his plans.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/fb/Best_Day_Ever_190.png/revision/latest/scale-to-width-down/500?cb=20251201192614"},{"name":"F.U.N. Song","rarity":"rare","id":"fun-song","subtitle":"Songs","details":"A spelling duet where SpongeBob teaches Plankton that F is for friends, while Plankton answers that F is for fire that burns down the whole town.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ee/F.U.N_071.png/revision/latest/scale-to-width-down/500?cb=20220208095108"},{"name":"Harold SquarePants","rarity":"uncommon","id":"harold-squarepants","subtitle":"Characters","details":"SpongeBob's father, a brown sponge with a mustache who loves his son dearly. He and Margaret visit the pineapple and cheer SpongeBob on.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/b1/Harold_Squarepants_model.png/revision/latest/scale-to-width-down/500?cb=20220807051128"},{"name":"Margaret SquarePants","rarity":"uncommon","id":"margaret-squarepants","subtitle":"Characters","details":"SpongeBob's mother, a kind sponge who bakes cookies and supports her son. She visits Bikini Bottom with Harold for family occasions.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8a/Margaret_model.png/revision/latest/scale-to-width-down/500?cb=20220807052035"},{"name":"Grandma SquarePants","rarity":"uncommon","id":"grandma-squarepants","subtitle":"Characters","details":"SpongeBob's sweet grandmother, who bakes cookies with love in every bite. Patrick loves visiting her house for treats and forehead kisses.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d3/Grandma_SquarePants_model_pose.png/revision/latest/scale-to-width-down/500?cb=20220807020833"},{"name":"Herb Star","rarity":"uncommon","id":"herb-star","subtitle":"Characters","details":"Patrick's father, a mustached starfish who is proud of his son. He and Margie once visited Patrick and doubted his rental house story.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ea/Herb_model_pose.jpg/revision/latest/scale-to-width-down/324?cb=20220805200119"},{"name":"Margie Star","rarity":"uncommon","id":"margie-star","subtitle":"Characters","details":"Patrick's mother, a caring starfish who visits her son in Bikini Bottom. She supports Patrick even when his stories stretch the truth.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/08/Margie_model_pose.jpg/revision/latest/scale-to-width-down/331?cb=20220805200209"},{"name":"Sam Star","rarity":"uncommon","id":"sam-star","subtitle":"Characters","details":"Patrick's big sister, a huge starfish with a short temper and a soft heart. She once visited Patrick and smashed her way through his home.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/94/Sam_Star.png/revision/latest/scale-to-width-down/352?cb=20240125074438"},{"name":"Betsy Krabs","rarity":"uncommon","id":"betsy-krabs","subtitle":"Characters","details":"Mr. Krabs' mother, who still treats her son like a little boy. She scolds him in embarrassing baby talk and once dated Plankton briefly.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/60/Betsy_Krabs_model_pose.png/revision/latest/scale-to-width-down/500?cb=20251231153109"},{"name":"Mrs. Tentacles","rarity":"uncommon","id":"mrs-tentacles","subtitle":"Characters","details":"Squidward's elderly mother, who lives in a house shaped like her own head. She sends her son sweaters and embarrassing childhood stories.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d3/Mrs._Tentacles_in_Momageddon.png/revision/latest/scale-to-width-down/233?cb=20240217072146"},{"name":"Captain Blue SquarePants","rarity":"uncommon","id":"captain-blue-squarepants","subtitle":"Characters","details":"SpongeBob's uncle, a retired police captain who tells tales of his patrol days. He taught young SpongeBob lessons over lemonade visits.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/0b/Captain_Blue_SquarePants_model.png/revision/latest/scale-to-width-down/456?cb=20260327071633"},{"name":"Blackjack SquarePants","rarity":"uncommon","id":"blackjack-squarepants","subtitle":"Characters","details":"SpongeBob's rough cousin, a former wrestler who once bullied him as a kid. SpongeBob feared his release until they met face to face again.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9d/BlackJack_model.png/revision/latest/scale-to-width-down/471?cb=20231117015455"},{"name":"Stanley S. SquarePants","rarity":"uncommon","id":"stanley-s-squarepants","subtitle":"Characters","details":"SpongeBob's tall cousin, whose touch destroys everything he handles. Mr. Krabs hired him at the Krusty Krab with disastrous results.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2e/Stanley_S._SquarePants.png/revision/latest?cb=20190520015036"},{"name":"Granny Plankton","rarity":"uncommon","id":"granny-plankton","subtitle":"Characters","details":"Plankton's sweet-seeming grandmother, who pinches cheeks and bakes for him. Beneath her kindness she is as scheming as her grandson.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/20/Granny_Plankton.jpg/revision/latest?cb=20230716194014"},{"name":"Chip Plankton II","rarity":"uncommon","id":"chip-plankton-ii","subtitle":"Characters","details":"Karen and Plankton's son, a chip who grew from vending machine to ATM. His parents proudly watched him graduate and start his career.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d7/Krabschip.jpg/revision/latest/scale-to-width-down/435?cb=20230306072046"},{"name":"Spot","rarity":"uncommon","id":"spot","subtitle":"Characters","details":"Plankton's loyal pet amoeba, a tiny green dog-like creature who barks and fetches. He once ran away and was adopted briefly by SpongeBob.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/76/Spot_model_pose.png/revision/latest/scale-to-width-down/395?cb=20260109084510"},{"name":"Snellie","rarity":"uncommon","id":"snellie","subtitle":"Characters","details":"Squidward's purebred pet snail, entered in the Great Snail Race against Gary. Her fancy pedigree could not beat Gary's heart at the finish.","image":"https://vignette.wikia.nocookie.net/spongebob/images/d/d1/The_Great_Snail_Race_016.png/revision/latest/scale-to-width-down/500?cb=20200927172310"},{"name":"Miss Tuffsy","rarity":"uncommon","id":"miss-tuffsy","subtitle":"Characters","details":"A tough female snail Gary fell for at the snail park. Her shell and attitude won him over during a day of snail watching and romance.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a4/Miss_Tuffsy_Portrait.jpg/revision/latest?cb=20210731001519"},{"name":"Rocky","rarity":"uncommon","id":"rocky","subtitle":"Characters","details":"Patrick's pet rock, entered in the Great Snail Race as his steed. The quiet rock won the race by simply rolling across the finish line.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/81/The_Great_Snail_Race_059.png/revision/latest/scale-to-width-down/500?cb=20200927172509"},{"name":"Clamu","rarity":"uncommon","id":"clamu","subtitle":"Characters","details":"A giant oyster at the Bikini Bottom Zoo, famed for spitting pearls. Her missing pearl turned out to be her baby, hatched before the crowd.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/98/Clamu.jpg/revision/latest/scale-to-width-down/500?cb=20211211194524"},{"name":"David Hasselhoff","rarity":"uncommon","id":"david-hasselhoff","subtitle":"Characters","details":"David Hasselhoff ferries SpongeBob and Patrick home across the ocean in the first movie, carrying them on his chest as a living speedboat.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/ed/14.jpg/revision/latest/scale-to-width-down/500?cb=20190410165751"},{"name":"No Name","rarity":"uncommon","id":"no-name","subtitle":"Characters","details":"A wild blue jellyfish SpongeBob befriended and tried to name Friend. It stung everyone it met until it returned to Jellyfish Fields.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/ce/Friend_%28No-Name%29_jellyfish_stock_art.png/revision/latest?cb=20181229183504"},{"name":"Jeffrey the Jellyfish","rarity":"uncommon","id":"jeffrey-the-jellyfish","subtitle":"Characters","details":"A friendly jellyfish kept at the Krusty Krab during the jellyfish migration. SpongeBob milked him for jelly to make Krabby Patties with jelly.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/cd/Jeffery_Jellyfish.png/revision/latest/scale-to-width-down/500?cb=20191001180017"},{"name":"Atomic Flounder","rarity":"uncommon","id":"atomic-flounder","subtitle":"Characters","details":"A retired superhero with atomic breath, once part of Mermaid Man's old team. Age made him cranky, but his powers stayed dangerously hot.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/bb/Old_atomic_flounder.png/revision/latest/scale-to-width-down/361?cb=20210923105352"},{"name":"Kelpy G","rarity":"uncommon","id":"kelpy-g","subtitle":"Characters","details":"A smooth jazz musician whose clarinet playing Squidward idolizes. His mellow concerts at the concert hall inspire Squidward's own dreams.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f8/Kelpy_G_model.png/revision/latest/scale-to-width-down/271?cb=20221022001638"},{"name":"Nick Withers","rarity":"uncommon","id":"nick-withers","subtitle":"Characters","details":"The stylish host of House Fancy, a television show touring fancy homes. He declared Squidward's chaotic house a work of art on live TV.","image":"https://vignette.wikia.nocookie.net/spongebob/images/b/b7/House-fancy-1.jpg/revision/latest/scale-to-width-down/500?cb=20140623193916"},{"name":"Gene Scallop","rarity":"uncommon","id":"gene-scallop","subtitle":"Characters","details":"Bikini Bottom's sharp-tongued food critic, whose reviews can make or break a restaurant. His column once praised the Krusty Krab's new chef.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/82/Gene_Scallop.png/revision/latest/scale-to-width-down/278?cb=20250725111811"},{"name":"Hans","rarity":"uncommon","id":"hans","subtitle":"Characters","details":"A giant live-action human hand that reaches into Bikini Bottom to help. He hands SpongeBob gifts, bandages, and once a whole ice cream cone.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/aa/SB_Patchy_Hand.png/revision/latest/scale-to-width-down/500?cb=20240107062543"},{"name":"Santa Claus","rarity":"uncommon","id":"santa-claus","subtitle":"Characters","details":"The jolly gift-giver SpongeBob brought to Bikini Bottom for its first Christmas. His sleigh ride ended with presents delivered by jellyfish power.","image":"https://vignette.wikia.nocookie.net/spongebob/images/a/a1/Christmas_Who_358.png/revision/latest/scale-to-width-down/500?cb=20190730121434"},{"name":"Tea at the Treedome","rarity":"uncommon","id":"tea-at-the-treedome","subtitle":"Episodes & Iconic Moments","details":"SpongeBob visits Sandy's air-filled treedome for the first time, tries to act fancy without water, and nearly dries out before Sandy saves him.","image":"https://vignette.wikia.nocookie.net/spongebob/images/1/1a/Tea_at_the_Treedome_title_card.png/revision/latest/scale-to-width-down/600?cb=20231228184655"},{"name":"Bubblestand","rarity":"uncommon","id":"bubblestand","subtitle":"Episodes & Iconic Moments","details":"SpongeBob opens a bubble stand charging twenty-five cents, teaches Squidward his secret technique, and a giant bubble carries the clarinetist away.","image":"https://vignette.wikia.nocookie.net/spongebob/images/7/75/Bubblestand_title_card.png/revision/latest/scale-to-width-down/600?cb=20240724055309"},{"name":"Plankton!","rarity":"uncommon","id":"plankton-episode","subtitle":"Episodes & Iconic Moments","details":"Tiny villain Plankton makes his first attempt on the formula by controlling SpongeBob's brain and steering him straight toward the Krusty Krab safe.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8c/Plankton%21_title_card.png/revision/latest/scale-to-width-down/600?cb=20240731002221"},{"name":"Naughty Nautical Neighbors","rarity":"uncommon","id":"naughty-nautical-neighbors","subtitle":"Episodes & Iconic Moments","details":"Squidward sabotages SpongeBob and Patrick's friendship with forged insults, then becomes the reluctant filling in their new best-friend sandwich.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e6/Naughty_Nautical_Neighbors_title_card.png/revision/latest/scale-to-width-down/600?cb=20240731013825"},{"name":"Jellyfishing","rarity":"uncommon","id":"jellyfishing","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick take a bandaged Squidward jellyfishing to cheer him up, and a huge queen jellyfish gives him a sting he will never forget.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/0a/Jellyfishing_title_card.png/revision/latest/scale-to-width-down/600?cb=20240730234345"},{"name":"Hall Monitor","rarity":"uncommon","id":"hall-monitor","subtitle":"Episodes & Iconic Moments","details":"Mrs. Puff lets SpongeBob serve as hall monitor, and his overzealous patrol of Bikini Bottom turns him into a wanted menace dubbed the Maniac.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/26/Hall_Monitor_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20170113010734"},{"name":"Sandy's Rocket","rarity":"uncommon","id":"sandys-rocket","subtitle":"Episodes & Iconic Moments","details":"SpongeBob and Patrick sneak aboard Sandy's rocket, mistake Bikini Bottom for the moon, and capture their neighbors believing they are aliens.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e7/Sandy%27s_Rocket_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20170113010752"},{"name":"Culture Shock","rarity":"uncommon","id":"culture-shock","subtitle":"Episodes & Iconic Moments","details":"Mr. Krabs stages a talent show to save slow business at the Krusty Krab, and Squidward's interpretive dance is upstaged by SpongeBob's mop act.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f0/Culture_Shock_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20170113010908"},{"name":"F.U.N.","rarity":"uncommon","id":"f-u-n","subtitle":"Episodes & Iconic Moments","details":"SpongeBob tries to befriend Plankton through a song about fun, and the tiny villain almost reforms before his true plan for the formula emerges.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/48/F.U.N._title_card.jpg/revision/latest/scale-to-width-down/600?cb=20170113011041"},{"name":"MuscleBob BuffPants","rarity":"uncommon","id":"musclebob-buffpants","subtitle":"Episodes & Iconic Moments","details":"SpongeBob buys inflatable Anchor Arms to impress Sandy, enters a weightlifting contest, and is exposed when the fake muscles pop on the beach.","image":"https://vignette.wikia.nocookie.net/spongebob/images/8/8e/MuscleBob_BuffPants_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304111657"},{"name":"Squidward the Unfriendly Ghost","rarity":"uncommon","id":"squidward-the-unfriendly-ghost","subtitle":"Episodes & Iconic Moments","details":"After a wax figure mishap, SpongeBob and Patrick believe Squidward is a ghost, and he milks their fear for pampering before the truth comes out.","image":"https://vignette.wikia.nocookie.net/spongebob/images/4/4c/Squidward_the_Unfriendly_Ghost_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304112116"},{"name":"Scaredy Pants","rarity":"uncommon","id":"scaredy-pants","subtitle":"Episodes & Iconic Moments","details":"Tired of being scared every Halloween, SpongeBob dresses as the Flying Dutchman, and the real Dutchman arrives offended by the cheap imitation.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/0c/Scaredy_Pants_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304112634"},{"name":"I Was a Teenage Gary","rarity":"uncommon","id":"i-was-a-teenage-gary","subtitle":"Episodes & Iconic Moments","details":"Squidward neglects Gary while housesitting, and snail plasma accidentally turns SpongeBob into a meowing snail that only Gary can understand.","image":"https://vignette.wikia.nocookie.net/spongebob/images/2/2a/I_Was_a_Teenage_Gary_title_card.jpg/revision/latest/scale-to-width-down/600?cb=20180714210336"},{"name":"SB-129","rarity":"uncommon","id":"sb-129","subtitle":"Episodes & Iconic Moments","details":"Squidward hides in a time machine, visits primitive Bikini Bottom and the far future, and learns that being alone is not the paradise he imagined.","image":"https://vignette.wikia.nocookie.net/spongebob/images/6/68/SB-129_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304113039"},{"name":"Sleepy Time","rarity":"uncommon","id":"sleepy-time","subtitle":"Episodes & Iconic Moments","details":"SpongeBob tours his friends' dreams while asleep, meddling in each one, until the dreamers unite to chase him out and reclaim their rest.","image":"https://vignette.wikia.nocookie.net/spongebob/images/0/03/Sleepy_Time_title_card.png/revision/latest/scale-to-width-down/600?cb=20231102105208"},{"name":"Valentine's Day","rarity":"uncommon","id":"valentines-day","subtitle":"Episodes & Iconic Moments","details":"SpongeBob plans a huge Valentine's surprise for Patrick at the carnival, and a delayed chocolate balloon heart nearly ruins their friendship.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f4/Valentine%27s_Day_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304113810"},{"name":"The Paper","rarity":"uncommon","id":"the-paper","subtitle":"Episodes & Iconic Moments","details":"Squidward discards a gum wrapper that SpongeBob turns into endless fun, then desperately trades away everything he owns to get the paper back.","image":"https://vignette.wikia.nocookie.net/spongebob/images/c/cc/The_Paper_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304114245"},{"name":"Hooky","rarity":"uncommon","id":"hooky","subtitle":"Episodes & Iconic Moments","details":"Mr. Krabs warns about mysterious hooks that lift fish away forever, but SpongeBob and Patrick keep playing on them until one catches for real.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e8/Hooky_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304115217"},{"name":"Mermaid Man and Barnacle Boy II","rarity":"uncommon","id":"mermaid-man-and-barnacle-boy-ii","subtitle":"Episodes & Iconic Moments","details":"SpongeBob wins Mermaid Man's conch shell, summons the heroes for trivial emergencies, and learns the signal is reserved for genuine danger.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/9e/Mermaid_Man_and_Barnacle_Boy_II_title_card.png/revision/latest/scale-to-width-down/600?cb=20230304115307"},{"name":"Your Shoe's Untied","rarity":"uncommon","id":"your-shoes-untied","subtitle":"Episodes & Iconic Moments","details":"SpongeBob forgets how to tie his shoes and hides his shame from everyone, until Gary reveals a surprising talent with laces of his very own.","image":"https://vignette.wikia.nocookie.net/spongebob/images/f/f2/Your_Shoe%27s_Untied_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626065811"},{"name":"No Free Rides","rarity":"uncommon","id":"no-free-rides","subtitle":"Episodes & Iconic Moments","details":"Mrs. Puff, desperate to be rid of SpongeBob, passes him at boating school, then steals his new boatmobile to undo her moment of weakness.","image":"https://vignette.wikia.nocookie.net/spongebob/images/e/e4/No_Free_Rides_title_card.png/revision/latest/scale-to-width-down/600?cb=20231104055306"},{"name":"I'm Your Biggest Fanatic","rarity":"uncommon","id":"im-your-biggest-fanatic","subtitle":"Episodes & Iconic Moments","details":"SpongeBob joins the Jellyspotters fan club and idolizes Kevin the sea cucumber, who uses the devoted fan as bait for a queen jellyfish sting.","image":"https://vignette.wikia.nocookie.net/spongebob/images/9/96/I%27m_Your_Biggest_Fanatic_title_card.png/revision/latest/scale-to-width-down/600?cb=20240626071054"}]});
